def cycpattern_check(a: str, b: str) -> bool:
    if not a or not b:
        return False

    len_b = len(b)
    len_a = len(a)

    if len_b > len_a:
        return False

    rotations = [b[i:] + b[:i] for i in range(len_b)]

    for rotation in rotations:
        if rotation in a:
            return True

    return False
